function navigate(route,{focus=true}={}){state.route=route;state.recordDetail=null;state.selectedSourceId=null;state.sourceInvoker=null;location.hash=route;render({focus});if(route==="saved")loadSavedLinks();if(["rentals","inbox"].includes(route))loadRentals();if(["travel","inbox"].includes(route))loadTravel();if(route==="household")loadHousehold()}
