  try{const picked=await window.familyPassportGoogleDrive.pick(),result=await window.familyPassportOcr.process(picked.file),m=picked.metadata,source=await window.familyPassportData.registerGoogleDriveSource({file_id:m.id,file_name:m.name,mime_type:m.mimeType,size_bytes:Number(m.size),modified_time:m.modifiedTime,provider_version:String(m.version),provider_checksum:m.md5Checksum||null,content_sha256:result.source.sha256,web_view_link:m.webViewLink||null});await window.familyPassportData.updateGoogleDriveSource(source.id,m);window.familyPassportPendingDriveSource=source.id;state.ocrCandidate={...result,category_id:state.householdData?.categories?.[0]?.id||"",external_source_id:source.id};announce("Exact Drive file selected and ready for confirmation");navigate("review");return}catch(error){if(error.code!=="cancelled"){state.ocrError=error.code==="drive_not_configured"?"Google Drive needs its client ID, restricted API key and project number.":error.message||"The Drive file could not be selected.";announce(state.ocrError)}}finally{state.ocrBusy=false}render({focus:true})
