async function reconcileGoogleDriveSources(){let checked=0;try{for(const source of state.driveSources){const meta=await window.familyPassportGoogleDrive.inspect(source.provider_file_id);const status=meta.inaccessible?"inaccessible":meta.missing?"missing":"active";await window.familyPassportData.updateGoogleDriveSource(source.id,meta,status);checked++}await loadHousehold();render({focus:true});announce(`${checked} linked Drive file${checked===1?"":"s"} checked`)}catch(error){state.dataError=error.message||"Drive reconciliation could not finish.";render({focus:true})}}
